package alerts

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/xity4uu-a11y/tradebox-local/internal/config"
)

// Alert represents a structured notification generated by the watchdog, latency probe, or journal parser.
type Alert struct {
	ID             string            `json:"id"`
	RuleKey        string            `json:"rule_key"`
	Severity       string            `json:"severity"` // info | warn | critical
	Category       string            `json:"category"` // watchdog | latency | journal | system
	Title          string            `json:"title"`
	Message        string            `json:"message"`
	Source         string            `json:"source"`
	Timestamp      time.Time         `json:"timestamp"`
	Metadata       map[string]string `json:"metadata,omitempty"`
	BypassCooldown bool              `json:"-"`
}

// ChannelResult records the HTTP outcome for a single notification destination.
type ChannelResult struct {
	Channel    string `json:"channel"`
	Status     string `json:"status"` // sent | failed
	HTTPStatus int    `json:"http_status,omitempty"`
	Error      string `json:"error,omitempty"`
}

// DispatchRecord captures the aggregate delivery outcome for one alert event.
type DispatchRecord struct {
	Alert     Alert           `json:"alert"`
	Status    string          `json:"status"` // sent | throttled | failed | partial | no_channels
	Channels  []ChannelResult `json:"channels"`
	CreatedAt time.Time       `json:"created_at"`
}

// ChannelsStatus summarizes which notification channels are configured and enabled.
type ChannelsStatus struct {
	Telegram    bool `json:"telegram"`
	Discord     bool `json:"discord"`
	Slack       bool `json:"slack"`
	Webhook     bool `json:"webhook"`
	CooldownSec int  `json:"cooldown_sec"`
}

// Dispatcher sends alerts across Telegram, Discord, Slack, and HMAC-SHA256 webhooks with per-rule cooldowns.
type Dispatcher struct {
	cfg        config.AlertsConfig
	client     *http.Client
	maxHistory int

	mu       sync.Mutex
	lastSent map[string]time.Time
	history  []DispatchRecord
	seq      int64
}

// NewDispatcher creates a new alert dispatcher using pure-Go net/http.
func NewDispatcher(cfg config.AlertsConfig, client *http.Client) *Dispatcher {
	if client == nil {
		client = &http.Client{Timeout: 8 * time.Second}
	}
	if strings.TrimSpace(cfg.Telegram.APIBaseURL) == "" {
		cfg.Telegram.APIBaseURL = "https://api.telegram.org"
	}
	return &Dispatcher{
		cfg:        cfg,
		client:     client,
		maxHistory: 200,
		lastSent:   make(map[string]time.Time),
		history:    make([]DispatchRecord, 0, 200),
	}
}

// Channels returns which alert channels are currently active.
func (d *Dispatcher) Channels() ChannelsStatus {
	return ChannelsStatus{
		Telegram:    d.cfg.Telegram.Enabled && d.cfg.Telegram.BotToken != "" && d.cfg.Telegram.ChatID != "",
		Discord:     d.cfg.Discord.Enabled && d.cfg.Discord.WebhookURL != "",
		Slack:       d.cfg.Slack.Enabled && d.cfg.Slack.WebhookURL != "",
		Webhook:     d.cfg.Webhook.Enabled && d.cfg.Webhook.URL != "",
		CooldownSec: d.cfg.CooldownSec,
	}
}

// History returns recent alert dispatch records, newest first.
func (d *Dispatcher) History(limit int) []DispatchRecord {
	d.mu.Lock()
	defer d.mu.Unlock()

	if limit <= 0 || limit > len(d.history) {
		limit = len(d.history)
	}
	out := make([]DispatchRecord, 0, limit)
	for i := len(d.history) - 1; i >= 0 && len(out) < limit; i-- {
		out = append(out, d.history[i])
	}
	return out
}

// Dispatch evaluates per-rule cooldown throttling and sends the alert to every enabled channel.
func (d *Dispatcher) Dispatch(ctx context.Context, alert Alert) DispatchRecord {
	now := time.Now().UTC()
	if alert.Timestamp.IsZero() {
		alert.Timestamp = now
	}
	if strings.TrimSpace(alert.Severity) == "" {
		alert.Severity = "info"
	}
	if strings.TrimSpace(alert.RuleKey) == "" {
		alert.RuleKey = alert.Category + ":" + alert.Title
	}

	d.mu.Lock()
	d.seq++
	if alert.ID == "" {
		alert.ID = fmt.Sprintf("alrt-%d-%d", now.Unix(), d.seq)
	}

	cooldown := time.Duration(d.cfg.CooldownSec) * time.Second
	if !alert.BypassCooldown && cooldown > 0 {
		if prev, ok := d.lastSent[alert.RuleKey]; ok && now.Sub(prev) < cooldown {
			rec := DispatchRecord{
				Alert:     alert,
				Status:    "throttled",
				Channels:  []ChannelResult{},
				CreatedAt: now,
			}
			d.appendHistoryLocked(rec)
			d.mu.Unlock()
			return rec
		}
	}
	d.lastSent[alert.RuleKey] = now
	d.mu.Unlock()

	var results []ChannelResult
	cs := d.Channels()

	if cs.Telegram {
		results = append(results, d.sendTelegram(ctx, alert))
	}
	if cs.Discord {
		results = append(results, d.sendDiscord(ctx, alert))
	}
	if cs.Slack {
		results = append(results, d.sendSlack(ctx, alert))
	}
	if cs.Webhook {
		results = append(results, d.sendWebhook(ctx, alert))
	}

	status := "no_channels"
	if len(results) > 0 {
		sentCount := 0
		for _, r := range results {
			if r.Status == "sent" {
				sentCount++
			}
		}
		switch {
		case sentCount == len(results):
			status = "sent"
		case sentCount == 0:
			status = "failed"
		default:
			status = "partial"
		}
	}

	rec := DispatchRecord{
		Alert:     alert,
		Status:    status,
		Channels:  results,
		CreatedAt: now,
	}

	d.mu.Lock()
	d.appendHistoryLocked(rec)
	d.mu.Unlock()
	return rec
}

func (d *Dispatcher) appendHistoryLocked(rec DispatchRecord) {
	if len(d.history) >= d.maxHistory {
		copy(d.history, d.history[1:])
		d.history[len(d.history)-1] = rec
		return
	}
	d.history = append(d.history, rec)
}

func (d *Dispatcher) sendTelegram(ctx context.Context, alert Alert) ChannelResult {
	base := strings.TrimRight(d.cfg.Telegram.APIBaseURL, "/")
	endpoint := fmt.Sprintf("%s/bot%s/sendMessage", base, d.cfg.Telegram.BotToken)

	var lines []string
	lines = append(lines, fmt.Sprintf("[%s] %s", strings.ToUpper(alert.Severity), alert.Title))
	lines = append(lines, alert.Message)
	if alert.Source != "" {
		lines = append(lines, "Source: "+alert.Source)
	}
	for _, k := range sortedKeys(alert.Metadata) {
		lines = append(lines, fmt.Sprintf("%s: %s", k, alert.Metadata[k]))
	}
	lines = append(lines, "Time: "+alert.Timestamp.UTC().Format(time.RFC3339))

	payload := map[string]any{
		"chat_id":                  d.cfg.Telegram.ChatID,
		"text":                     strings.Join(lines, "\n"),
		"disable_web_page_preview": true,
	}
	return d.postJSON(ctx, "telegram", endpoint, payload, nil)
}

func (d *Dispatcher) sendDiscord(ctx context.Context, alert Alert) ChannelResult {
	color := 0x2B6CB0 // muted slate blue (info)
	switch strings.ToLower(alert.Severity) {
	case "critical":
		color = 0xB42318 // muted crimson
	case "warn":
		color = 0xB7791F // muted amber
	}

	fields := []map[string]any{
		{"name": "Severity", "value": strings.ToUpper(alert.Severity), "inline": true},
		{"name": "Category", "value": alert.Category, "inline": true},
	}
	if alert.Source != "" {
		fields = append(fields, map[string]any{"name": "Source", "value": alert.Source, "inline": true})
	}
	for _, k := range sortedKeys(alert.Metadata) {
		fields = append(fields, map[string]any{"name": k, "value": alert.Metadata[k], "inline": true})
	}

	payload := map[string]any{
		"username": "TradeBox Local",
		"embeds": []map[string]any{
			{
				"title":       alert.Title,
				"description": alert.Message,
				"color":       color,
				"fields":      fields,
				"timestamp":   alert.Timestamp.UTC().Format(time.RFC3339),
			},
		},
	}
	return d.postJSON(ctx, "discord", d.cfg.Discord.WebhookURL, payload, nil)
}

func (d *Dispatcher) sendSlack(ctx context.Context, alert Alert) ChannelResult {
	summary := fmt.Sprintf("[%s] %s - %s", strings.ToUpper(alert.Severity), alert.Title, alert.Message)
	blocks := []map[string]any{
		{
			"type": "header",
			"text": map[string]any{
				"type":  "plain_text",
				"text":  fmt.Sprintf("[%s] %s", strings.ToUpper(alert.Severity), alert.Title),
				"emoji": false,
			},
		},
		{
			"type": "section",
			"text": map[string]any{
				"type": "mrkdwn",
				"text": alert.Message,
			},
		},
		{
			"type": "context",
			"elements": []map[string]any{
				{
					"type": "mrkdwn",
					"text": fmt.Sprintf("Category: %s | Source: %s | Time: %s",
						alert.Category, alert.Source, alert.Timestamp.UTC().Format(time.RFC3339)),
				},
			},
		},
	}

	payload := map[string]any{
		"text":   summary,
		"blocks": blocks,
	}
	return d.postJSON(ctx, "slack", d.cfg.Slack.WebhookURL, payload, nil)
}

func (d *Dispatcher) sendWebhook(ctx context.Context, alert Alert) ChannelResult {
	bodyBytes, err := json.Marshal(alert)
	if err != nil {
		return ChannelResult{Channel: "webhook", Status: "failed", Error: err.Error()}
	}

	headers := map[string]string{
		"X-TradeBox-Timestamp": strconv.FormatInt(alert.Timestamp.UTC().Unix(), 10),
		"X-TradeBox-Event":     alert.Category,
	}
	if d.cfg.Webhook.Secret != "" {
		headers["X-TradeBox-Signature"] = SignPayload(d.cfg.Webhook.Secret, bodyBytes)
	}
	return d.postRaw(ctx, "webhook", d.cfg.Webhook.URL, bodyBytes, headers)
}

func (d *Dispatcher) postJSON(ctx context.Context, channel, url string, payload any, headers map[string]string) ChannelResult {
	bodyBytes, err := json.Marshal(payload)
	if err != nil {
		return ChannelResult{Channel: channel, Status: "failed", Error: err.Error()}
	}
	return d.postRaw(ctx, channel, url, bodyBytes, headers)
}

func (d *Dispatcher) postRaw(ctx context.Context, channel, url string, body []byte, headers map[string]string) ChannelResult {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(body))
	if err != nil {
		return ChannelResult{Channel: channel, Status: "failed", Error: err.Error()}
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "tradebox-local/1.0.0")
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	resp, err := d.client.Do(req)
	if err != nil {
		return ChannelResult{Channel: channel, Status: "failed", Error: err.Error()}
	}
	defer func() { _ = resp.Body.Close() }()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 4096))

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ChannelResult{
			Channel:    channel,
			Status:     "failed",
			HTTPStatus: resp.StatusCode,
			Error:      fmt.Sprintf("unexpected HTTP status %d", resp.StatusCode),
		}
	}
	return ChannelResult{
		Channel:    channel,
		Status:     "sent",
		HTTPStatus: resp.StatusCode,
	}
}

// SignPayload returns the HMAC-SHA256 signature formatted as "sha256=<hex>".
func SignPayload(secret string, payload []byte) string {
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(payload)
	return "sha256=" + hex.EncodeToString(mac.Sum(nil))
}

// VerifySignature validates an incoming X-TradeBox-Signature header in constant time.
func VerifySignature(secret string, payload []byte, signatureHeader string) bool {
	expected := SignPayload(secret, payload)
	return hmac.Equal([]byte(expected), []byte(signatureHeader))
}

func sortedKeys(m map[string]string) []string {
	if len(m) == 0 {
		return nil
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
